#include <d3dcompiler.h>
#include <cwchar>

// XLWebEngineUI: optional FXC, safe on Win7 without d3dcompiler_47.dll.
// Use the engine image directory first, then the Windows system directory.
// Never search the current working directory. Static initialization is thread-safe.
template<class... Args>
static HRESULT xl_optional_D3DCompile(Args... args) {
    struct Compiler {
        HMODULE module = nullptr;
        decltype(&D3DCompile) compile = nullptr;
        Compiler() {
            HMODULE owner = nullptr;
            wchar_t path[32768]{};
            if (GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS |
                                   GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                                   reinterpret_cast<LPCWSTR>(&xl_optional_D3DCompile<Args...>), &owner)) {
                DWORD length = GetModuleFileNameW(owner, path, 32768);
                if (length && length < 32768) {
                    wchar_t* slash = wcsrchr(path, L'\\');
                    if (slash && (slash - path) + 20 < 32768) {
                        wcscpy(slash + 1, L"d3dcompiler_47.dll");
                        module = LoadLibraryW(path);
                    }
                }
            }
            if (!module) {
                UINT length = GetSystemDirectoryW(path, 32768);
                if (length && length + 21 < 32768) {
                    wcscat(path, L"\\d3dcompiler_47.dll");
                    module = LoadLibraryW(path);
                }
            }
            if (module) compile = reinterpret_cast<decltype(compile)>(GetProcAddress(module, "D3DCompile"));
        }
        ~Compiler() { if (module) FreeLibrary(module); }
    };
    static const Compiler compiler;
    return compiler.compile ? compiler.compile(args...) : E_NOINTERFACE;
}

// Prefer the compiler explicitly chosen for this device; keep optional FXC as default.
template<class... Args>
static HRESULT xl_device_D3DCompile(GrD3DGpu* gpu, Args... args) {
    if (auto compiler = gpu->shaderCompiler()) return compiler(args...);
    return xl_optional_D3DCompile(args...);
}
